\draw[black,<->](0,-4.4)--(0,4.4);\path(0,4.4)node[above]{$y$};
\foreach \v in {-3,-2,-1,1,2,3}{\draw[black](\v,.08)--(\v,-.08);\path(\v,-.08)node[below,font=\fontsize{8.5}{10}\selectfont]{$\v$};\draw[black](.08,\v)--(-.08,\v);\path(-.08,\v)node[left,font=\fontsize{8.5}{10}\selectfont]{$\v$};}
\draw[imageblue,dashed](-3,2)--(-3,-2);
\fill[black](-3,2)circle(2pt);\path(-3,2)node[above left]{$D$};
